441	async fn remote(state : Json, script : String, stage : String) -> String {
442	  let args = mux_ssh_args(state)
443	  command(
444	    workspace_program(state, "ssh"),
445	    args + [script],
446	    stage,
447	    environment=workspace_environment(state),
448	    cwd?=workspace_directory(state).map(path => path[:]),
449	    target?=field(state, "workspaceId").map(value => {
