452	      } else {
453	        ""
454	      }
455	    }),
456	  )
457	}
458	
459	///|
460	fn up_result(output : String) -> Json raise {
461	  let results = []
462	  for line in output.split("\n") {
463	    if line.trim() != "" {
464	      let parsed = @json.parse(line.to_owned())
465	      if field(parsed, "kind") == Some(Json::string("result")) {
466	        results.push(parsed)
467	      }
468	    }
469	  }
470	  guard results.length() == 1 &&
471	    field(results[0], "outcome") == Some(Json::string("success")) else {
472	    raise AdapterError(
473	      "Devsy did not return exactly one successful workspace result",
474	    )
475	  }
476	  results[0]
477	}
